import { useEffect, useState } from 'react';
import { useData } from 'vike-react/useData';
import { useTranslation } from 'react-i18next';
import { useQueryClient } from '@tanstack/react-query';
import { LOCAL_STORAGE_KEY, StaticReadingMode } from '../components/StaticReadingMode';
import type { PageData } from './+data';
import { Box, Stack } from 'styled-system/jsx';
import { Text } from '~/components/ui/text';
import { Button } from '~/components/ui/button';
import MainContentAndRightSidebar from '~/components/layout/MainContentAndRightSidebar';
import { parseMonthYear } from '~/utils/date';

export default function Page() {
  const { monthsYears, events, latestTweetId }: PageData = useData();
  const [selectedMonthYear, setSelectedMonthYear] = useState<string | null>(null);
  const [currentMonthYear, setCurrentMonthYear] = useState<string | null>(null);
  const [lastReadTweetId, setLastReadTweetId] = useState<string | null | undefined>(undefined);

  const queryClient = useQueryClient();
  const { t, i18n } = useTranslation();

  const sortedMonthsYears = monthsYears.sort((a, b) => a.monthYear.localeCompare(b.monthYear));

  useEffect(() => {
    setLastReadTweetId(localStorage.getItem(LOCAL_STORAGE_KEY));
  }, []);

  useEffect(() => {
    if (selectedMonthYear) {
      const monthData = monthsYears.find((m) => m.monthYear === selectedMonthYear);
      if (monthData) {
        handleSelectTweet(monthData.firstTweetId);
      }
      setSelectedMonthYear(null);
    }
  }, [selectedMonthYear, monthsYears, queryClient]);

  const handleSelectTweet = (id: string) => {
    setLastReadTweetId(id);
    queryClient.resetQueries({ queryKey: ['static-tweets'] });
    localStorage.setItem(LOCAL_STORAGE_KEY, id);
  };

  return (
    <MainContentAndRightSidebar
      rightSidebarContent={({ close }) => (
        <Stack gap="4" h="full" p="4">
          <Box mt="4">
            <Text mb="2" fontWeight="bold">
              {t('bluebird.readingMode.months')}
            </Text>
            <Stack gap="1">
              {sortedMonthsYears.map((my) => (
                <Button
                  data-active={currentMonthYear === my.monthYear ? 'true' : undefined}
                  key={my.monthYear}
                  variant="ghost"
                  size="lg"
                  onClick={() => {
                    if (currentMonthYear !== my.monthYear) {
                      setSelectedMonthYear(my.monthYear);
                    } else {
                      setSelectedMonthYear(null);
                    }
                    close();
                  }}
                  justifyContent="flex-start"
                  _active={{ bg: 'bg.emphasized' }}
                >
                  {parseMonthYear(my.monthYear).toLocaleString(i18n.language, {
                    month: 'long',
                    year: 'numeric',
                    timeZone: 'UTC'
                  })}{' '}
                  <Text as="span" color="fg.subtle" fontSize="sm">
                    ({my.count})
                  </Text>
                </Button>
              ))}
              {latestTweetId && (
                <Button
                  variant="ghost"
                  size="lg"
                  onClick={() => {
                    handleSelectTweet(latestTweetId);
                    close();
                  }}
                  justifyContent="flex-start"
                  _active={{ bg: 'bg.emphasized' }}
                >
                  {t('bluebird.readingMode.latest')}
                </Button>
              )}
            </Stack>
          </Box>
          <Box borderRadius="md" mt="4" p="2" color="text.subtle" fontSize="xs" bg="bg.subtle">
            {t('bluebird.sidebar.aiTranslationWarning')}
          </Box>
        </Stack>
      )}
    >
      {lastReadTweetId !== undefined && (
        <StaticReadingMode
          monthsYears={sortedMonthsYears}
          lastReadTweetId={lastReadTweetId}
          onCurrentMonthYearChange={setCurrentMonthYear}
          events={events}
          useEnglishName
          tweetPath="/tweets/en"
        />
      )}
    </MainContentAndRightSidebar>
  );
}
